#include "target/source/codegen_c.h"

namespace tvm {
namespace codegen {

class CodeGenTileLangAscendPto final : public CodeGenC {
public:
  CodeGenTileLangAscendPto(std::string platform);
  std::string Finish();
  // override behavior
  void PrintFuncPrefix(std::ostream &os) final;
