// Returns floor(log2(x)). Asserts x is a power of 2.
static int Log2AssertPowerOf2(int x) {
  int r = 0;
  while (x > 1) {
    ICHECK_EQ(x & 1, 0) << "log2 expects power-of-2 input, got: " << x;
    x >>= 1;
    ++r;
  }
  return r;
}

